/**
 * MDX Utilities for Salt Core Blog
 *
 * Uses Velite for content processing and type generation.
 * Types are auto-generated by Velite in .velite/index.d.ts
 */

import { posts, changelog } from '@/.velite'

// Re-export types (auto-generated by Velite)
export type { Post, ChangelogEntry } from '@/.velite'

/**
 * Get all published blog posts, sorted by date (newest first)
 */
export function getAllPosts() {
  return posts
    .filter(post => post.published)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
}

/**
 * Get a single blog post by slug
 */
export function getPostBySlug(slug: string) {
  return posts.find(post => post.slug === slug && post.published)
}

/**
 * Get all published changelog entries, sorted by date (newest first)
 */
export function getAllChangelog() {
  return changelog
    .filter(entry => entry.published)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
}

/**
 * Get recent posts (for homepage, sidebar, etc.)
 */
export function getRecentPosts(count: number = 3) {
  return getAllPosts().slice(0, count)
}

/**
 * Get posts by category
 */
export function getPostsByCategory(category: string) {
  return getAllPosts().filter(post => post.category === category)
}

/**
 * Get posts by tag
 */
export function getPostsByTag(tag: string) {
  return getAllPosts().filter(post => post.tags.includes(tag))
}

/**
 * Get all unique tags from published posts
 */
export function getAllTags() {
  const tags = new Set<string>()
  getAllPosts().forEach(post => post.tags.forEach(tag => tags.add(tag)))
  return Array.from(tags).sort()
}

/**
 * Get all unique categories from published posts
 */
export function getAllCategories() {
  const categories = new Set<string>()
  getAllPosts().forEach(post => categories.add(post.category))
  return Array.from(categories).sort()
}
